CREATE OR REPLACE FUNCTION public.protect_workspace_admin() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF OLD.role='admin' AND (TG_OP='DELETE' OR NEW.role<>'admin') THEN RAISE EXCEPTION 'Administrators must retain full access'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION public.can_access_employee_document(_employee uuid,_shared boolean) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT (public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'hr')) OR (_shared AND _employee=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE user_id=_employee AND deleted_at IS NULL)); $$;
CREATE POLICY workspace_storage_gate ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (CASE WHEN bucket_id='training-docs' THEN public.has_workspace_access(auth.uid(),'training') WHEN bucket_id='field-photos' THEN public.has_workspace_access(auth.uid(),'field') OR public.has_workspace_access(auth.uid(),'security') WHEN bucket_id='incident-audio' THEN public.has_workspace_access(auth.uid(),'security') ELSE true END) WITH CHECK (CASE WHEN bucket_id='training-docs' THEN public.has_workspace_access(auth.uid(),'training') WHEN bucket_id='field-photos' THEN public.has_workspace_access(auth.uid(),'field') OR public.has_workspace_access(auth.uid(),'security') WHEN bucket_id='incident-audio' THEN public.has_workspace_access(auth.uid(),'security') ELSE true END);
CREATE POLICY workspace_settings_insert_gate ON public.company_settings AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(public.has_workspace_access(auth.uid(),'settings'));
CREATE POLICY workspace_simulation_gate ON public.attendance_simulation_clock AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_workspace_access(auth.uid(),'attendance'));
CREATE POLICY workspace_simulated_punch_gate ON public.simulated_attendance_punches AS RESTRICTIVE FOR SELECT TO authenticated USING(public.has_workspace_access(auth.uid(),'attendance'));